export interface FrontmatterResult {
  data: Record<string, unknown>;
  body: string;
}

export class FrontmatterError extends Error {
  readonly line: number;
  constructor(message: string, line: number) {
    super(message);
    this.name = 'FrontmatterError';
    this.line = line;
  }
}

export function parseFrontmatter(src: string): FrontmatterResult {
  if (!src.startsWith('---\n')) {
    return { data: {}, body: src };
  }
  const end = src.indexOf('\n---\n', 4);
  if (end === -1) {
    throw new FrontmatterError('unterminated frontmatter block', 1);
  }
  const raw = src.slice(4, end);
  const body = src.slice(end + 5);
  return { data: parseYamlish(raw), body };
}

function parseYamlish(raw: string): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [i, lineText] of raw.split('\n').entries()) {
    if (!lineText.trim()) continue;
    const sep = lineText.indexOf(':');
    if (sep === -1) {
      throw new FrontmatterError('expected key: value', i + 2);
    }
    out[lineText.slice(0, sep).trim()] = lineText.slice(sep + 1).trim();
  }
  return out;
}

